SELECT 
FROM TBL_FINANCING_MONITORING
WHERE DELETE_FLAG = 0

    AND ALERT_TYPE = #{alertType}


    AND ALERT_LEVEL = #{alertLevel}


    AND ALERT_STATUS = #{alertStatus}


    AND COMPANY_ID = #{companyId}


    AND RELATED_FINANCING_ID = #{relatedFinancingId}


    AND ALERT_DATE >= #{alertStartDate}


    AND ALERT_DATE <= #{alertEndDate}


    AND HANDLER_ID = #{handlerId}


    AND ALERT_MESSAGE LIKE CONCAT('%', #{keyword}, '%')

ORDER BY ALERT_DATE DESC

SELECT COUNT(*)
FROM TBL_FINANCING_MONITORING
WHERE DELETE_FLAG = 0

    AND ALERT_TYPE = #{alertType}


    AND ALERT_LEVEL = #{alertLevel}


    AND ALERT_STATUS = #{alertStatus}


    AND COMPANY_ID = #{companyId}


    AND RELATED_FINANCING_ID = #{relatedFinancingId}


    AND ALERT_DATE >= #{alertStartDate}


    AND ALERT_DATE <= #{alertEndDate}


    AND HANDLER_ID = #{handlerId}


    AND ALERT_MESSAGE LIKE CONCAT('%', #{keyword}, '%')

SELECT ALERT_LEVEL, COUNT(*) as count FROM TBL_FINANCING_MONITORING WHERE DELETE_FLAG = 0
AND COMPANY_ID = #{companyId}
GROUP BY ALERT_LEVEL ORDER BY CASE ALERT_LEVEL WHEN 'HIGH' THEN 1 WHEN 'MEDIUM' THEN 2 WHEN 'LOW' THEN 3 ELSE 4 END
